CREATE OR REPLACE FUNCTION public.ensure_account() RETURNS public.accounts LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE v_account public.accounts; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Login necessário'; END IF; PERFORM pg_advisory_xact_lock(849275); INSERT INTO public.accounts(user_id) VALUES(auth.uid()) ON CONFLICT (user_id) DO NOTHING; IF NOT EXISTS (SELECT 1 FROM public.user_roles WHERE role = 'admin') THEN INSERT INTO public.user_roles(user_id, role) VALUES(auth.uid(), 'admin') ON CONFLICT DO NOTHING; END IF; SELECT * INTO v_account FROM public.accounts WHERE user_id = auth.uid(); RETURN v_account; END $$;